<template><article class="card tip-card"><div class="tip-top"><span class="tag">{{pick.league||'Football'}}</span><div class="tip-status"><span v-if="pick.status==='won'" class="result-badge won">WON</span><span v-else-if="pick.status==='lost'" class="result-badge lost">LOST</span><span v-else-if="pick.status==='void'" class="result-badge void">VOID</span><span v-else class="status-badge published">PUBLISHED</span><span v-if="pick.isPremium" class="confidence premium-lock">🔒 PREMIUM</span><span class="confidence" v-else-if="pick.confidence">{{pick.confidence}}%</span></div></div><div v-if="pick.matchId?.homeTeamId || pick.matchId?.awayTeamId" class="fixture-teams"><div><TeamLogo :src="pick.matchId?.homeTeamId?.logo" :name="pick.matchId?.homeTeamId?.name" size="sm"/><b>{{pick.matchId?.homeTeamId?.shortName||pick.matchId?.homeTeamId?.name||fixture}}</b></div><span v-if="pick.matchId?.status==='finished'" class="feed-score">{{pick.matchId?.homeScore}} : {{pick.matchId?.awayScore}}</span><span v-else>vs</span><div><b>{{pick.matchId?.awayTeamId?.shortName||pick.matchId?.awayTeamId?.name||'Away'}}</b><TeamLogo :src="pick.matchId?.awayTeamId?.logo" :name="pick.matchId?.awayTeamId?.name" size="sm"/></div></div><div v-else class="fixture">{{fixture}}</div><RouterLink v-if="!pick.locked" :to="`/predictions/${pick._id}`" class="prediction-link"><div class="prediction">{{pick.prediction}}</div></RouterLink><div v-else class="prediction locked-prediction">🔒 Premium prediction</div><div class="meta">{{formatDate(pick.createdAt||pick.publishedAt)}} · @{{pick.tipsterId?.name||'tipster'}}</div><div class="tip-bottom"><span class="odds">{{pick.locked?'Premium access required':`Odds ${Number(pick.odds||0).toFixed(2)}`}}</span><RouterLink v-if="pick.locked" to="/subscription" class="btn">Unlock Premium</RouterLink><button v-else class="btn" @click="handlePlay">{{auth.isLoggedIn?'Play pick':'Sign up to play'}}</button></div><div v-if="show" class="play-box"><b>Add to My Picks</b><p class="muted small">Choose a virtual stake to track your potential return. No payment is taken here.</p><input v-model.number="stake" type="number" min="1" step="1" placeholder="Stake (GHS)"/><div class="small" style="margin:8px 0">Potential return: <b>GHS {{(stake*Number(pick.odds||1)).toFixed(2)}}</b></div><div style="display:flex;gap:8px"><button class="btn" @click="save">{{busy?'Saving…':'Add pick'}}</button><button class="ghost" @click="show=false">Cancel</button></div><div v-if="error" class="error" style="margin-top:8px">{{error}}</div></div></article></template>
<script setup lang="ts">import {computed,ref} from 'vue';import {useAuth} from '../stores/auth';import {api} from '../services/api';import {useRouter,RouterLink} from 'vue-router';import TeamLogo from './TeamLogo.vue';const props=defineProps<{pick:any}>();const auth=useAuth(),router=useRouter(),show=ref(false),stake=ref(10),busy=ref(false),error=ref('');const fixture=computed(()=>props.pick.fixture||'Upcoming fixture');function formatDate(v:any){return v?new Date(v).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'Published pick'}function handlePlay(){if(!auth.isLoggedIn){router.push({path:'/login',query:{redirect:'/picks'}});return}show.value=true}async function save(){busy.value=true;error.value='';try{await api.post('/me/picks',{predictionId:props.pick._id,stake:stake.value});show.value=false;alert('Pick added to My Picks')}catch(e:any){error.value=e.message}finally{busy.value=false}}</script>
<style scoped> .premium-lock{color:#8b4cf6}.locked-prediction{color:#8b4cf6;font-weight:900;padding:8px 0} .tip-status{display:flex;align-items:center;gap:5px}.fixture-teams{display:flex;align-items:center;justify-content:center;gap:10px;margin:15px 0;font-size:13px}.fixture-teams>div{display:flex;align-items:center;gap:6px;min-width:0}.fixture-teams>div b{max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fixture-teams span{color:var(--muted);font-size:11px}.feed-score{font-weight:900;color:#17243b!important;white-space:nowrap} .play-box{margin-top:15px;padding-top:15px;border-top:1px solid var(--line)}.play-box input{width:100%;padding:10px;border:1px solid var(--line);border-radius:9px;margin:8px 0}</style>
